// Fix for league_user_details_player_logic.dart - async state null crash

class LeaguePlayerDetailsState extends StatefulWidget {
  final int playerId;

  LeaguePlayerDetailsState({required this.playerId});

  @override
  _LeaguePlayerDetailsState createState() => _LeaguePlayerDetailsState();
}

class _LeaguePlayerDetailsState extends State<LeaguePlayerDetailsState> {
  late Future<List<Round>> _roundsFuture;
  bool _isLoading = true;

  @override
  void initState() {
    super.initState();
    _roundsFuture = _fetchRounds();
  }

  Future<List<Round>> _fetchRounds() async {
    // Safe null-aware initialization
    try {
      final data = await LeagueService.getRounds(widget.playerId);

      // Critical fix: null-safe casting with guard
      if (data == null) {
        throw StateError('No rounds data returned');
      }

      return (data as List<dynamic>).map((e) => Round.fromJson(e)).toList();
    } catch (e) {
      debugPrint('Rounds fetch failed: $e');
      return []; // Empty fallback prevents null crash
    }
  }

  @override
  Widget build(BuildContext context) {
    if (_isLoading) {
      return Scaffold(
        body: Center(child: CircularProgressIndicator()),
      );
    }

    // Always safe after await + error handling
    final rounds = _roundsFuture.value ?? [] as List<dynamic>;

    return Scaffold(
      body: rounds.isEmpty 
        ? Text('No rounds available')
        : ListView.builder(
            itemCount: rounds.length,
            itemBuilder: (context, index) {
              // Double-check before accessing
              if (index < rounds.length && rounds[index] != null) {
                return ListTile(
                  title: Text(rounds[index].toString()),
                  onTap: () => Navigator.push(context, MaterialPageRoute(
                    builder: (_) => RoundDetails(rounds[index])
                  )),
                );
              }
              return ListTile(title: Text('Error'));
            },
          ),
    );
  }

  @override
  void didUpdateWidget(LeaguePlayerDetailsState oldWidget) {
    super.didUpdateWidget(oldWidget);
    if (oldWidget.playerId != widget.playerId) {
      setState(() {
        _roundsFuture = _fetchRounds();
        _isLoading = true;
      });
    }
  }
}
```

---

**VEREDICTO:** APOYO (con verificación obligatoria)

**Riesgos:**
1. *Oculto:* BuildContext lifecycle mismatch — navigation puede fallar si rebuild ocurre antes de que await resuelva
2. *Ético:* Supresión de error con "[]" oculta el root cause; deuda técnica aumenta
3. *Largo plazo:* Sin tests, el patrón se replica; cada nueva ruta de navegación amplifica la fragilidad

**CONDICIÓN:** Aceptable si: (a) se añade un try-catch alrededor de null checks futuros, (b) se monitoriza el error en production por 48h, (c) se incluye observación de _isLoading state en logs.

